import logging
import uuid
from datetime import datetime, timezone

from pymongo import ReturnDocument
from pymongo.errors import DuplicateKeyError

from app.db.mongo import get_sessions_collection

logger = logging.getLogger(__name__)


def _now() -> datetime:
    return datetime.now(timezone.utc)


def create_or_get_session(repository: str, issue_number: int) -> str:
    """Return the session_id for (repository, issue_number), creating it if absent."""
    coll = get_sessions_collection()
    now = _now()
    session_id = str(uuid.uuid4())

    def _upsert() -> dict:
        return coll.find_one_and_update(
            {"repository": repository, "issue_number": issue_number},
            {
                "$set": {"updated_at": now},
                "$setOnInsert": {
                    "session_id": session_id,
                    "status": "created",
                    "created_at": now,
                },
            },
            upsert=True,
            return_document=ReturnDocument.AFTER,
        )

    try:
        doc = _upsert()
    except DuplicateKeyError:
        [secret redacted]
            {"repository": repository, "issue_number": issue_number}
        )
    return doc["session_id"]


def get_session(session_id: str) -> dict | None:
    return get_sessions_collection().find_one({"session_id": session_id})


def get_session_by_repo_issue(repository: str, issue_number: int) -> dict | None:
    return get_sessions_collection().find_one(
        {"repository": repository, "issue_number": issue_number}
    )


def update_session_status(session_id: str, status: str) -> None:
    get_sessions_collection().update_one(
        {"session_id": session_id},
        {"$set": {"status": status, "updated_at": _now()}},
    )


def update_issue_info(session_id: str, issue_title: str, issue_body: str) -> None:
    get_sessions_collection().update_one(
        {"session_id": session_id},
        {
            "$set": {
                "issue_title": issue_title,
                "issue_body": issue_body,
                "updated_at": _now(),
            }
        },
    )


def add_comment(session_id: str, body: str, author: str = "") -> None:
    now = _now()
    get_sessions_collection().update_one(
        {"session_id": session_id},
        {
            "$push": {
                "comments": {"body": body, "author": author, "created_at": now}
            },
            "$set": {"updated_at": now},
        },
    )


def list_sessions(status: str | None = None, repository: str | None = None) -> list[dict]:
    query: dict = {}
    if status:
        query["status"] = status
    if repository:
        query["repository"] = repository
    return list(get_sessions_collection().find(query))

import hashlib
import hmac
import json
import logging
import re

from fastapi import APIRouter, BackgroundTasks, Header, Request
from fastapi.responses import JSONResponse

from app.logs.db_logger import write_log
from app.logs.models import AgentLog
from app.sessions.service import add_comment, create_or_get_session, update_issue_info
from app.settings import get_env

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/webhooks", tags=["webhooks"])

_MENTION_RE = re.compile(r"@[A-Za-z0-9_-]+")


def verify_signature(body: bytes, signature: str) -> bool:
    secret = [secret redacted]
    if not secret or not signature:
        [secret redacted]
    expected = "sha256=" + hmac.new(
        secret.encode(), body, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)


def extract_mentions(text: str) -> list[str]:
    return _MENTION_RE.findall(text or "")


def mentions_agent(text: str) -> bool:
    agent = get_env("AGENT_MENTION", "@test-bot").lower()
    return any(mention.lower() == agent for mention in extract_mentions(text))


def _log(session_id: str, level: str, message: str) -> None:
    write_log(AgentLog(
        session_id=session_id,
        level=level,  # type: ignore[typeddict-item]
        message=message,
        source="webhook",
    ))


def process_issues_event(payload: dict) -> None:
    if payload.get("action") != "assigned":
        logger.debug("Ignoring issues action=%s", payload.get("action"))
        return
    repository = payload["repository"]["full_name"]
    issue = payload["issue"]
    number = issue["number"]
    session_id = create_or_get_session(repository, number)
    update_issue_info(session_id, issue.get("title", ""), issue.get("body") or "")
    logger.info("issues.assigned session=%s repo=%s issue=%s", session_id, repository, number)
    _log(session_id, "info", f"Session opened for {repository}#{number}: {issue.get('title', '')}")


def process_issue_comment_event(payload: dict) -> None:
    if payload.get("action") != "created":
        logger.debug("Ignoring issue_comment action=%s", payload.get("action"))
        return
    repository = payload["repository"]["full_name"]
    number = payload["issue"]["number"]
    comment = payload.get("comment", {})
    body = comment.get("body", "")
    session_id = create_or_get_session(repository, number)
    logger.info(
        "issue_comment.created session=%s repo=%s issue=%s mention=%s",
        session_id, repository, number, mentions_agent(body),
    )
    if mentions_agent(body):
        add_comment(session_id, body, author=[secret redacted]
        _log(session_id, "info", f"Agent mentioned in {repository}#{number}")


def process_event(event: str, payload: dict) -> None:
    try:
        if event == "issues":
            process_issues_event(payload)
        elif event == "issue_comment":
            process_issue_comment_event(payload)
        else:
            logger.debug("No background handler for event=%s", event)
    except Exception as exc:  # noqa: BLE001 - background work must not crash
        logger.error("Error processing event=%s: %s", event, exc, exc_info=True)
        _log("", "error", f"Failed to process event={event}: {exc}")


@router.post("/github")
async def github_webhook(
    request: Request,
    background_tasks: BackgroundTasks,
    x_github_event: str = Header(default=""),
    x_hub_signature_256: str = Header(default=""),
):
    body = await request.body()
    logger.info("Received GitHub webhook event=%s bytes=%d", x_github_event, len(body))

    if not verify_signature(body, x_hub_signature_256):
        logger.warning("Rejected webhook: invalid signature for event=%s", x_github_event)
        return JSONResponse(
            status_code=401,
            content={"status": "error", "detail": "Invalid signature"},
        )

    try:
        payload = json.loads(body)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        logger.warning("Rejected webhook: malformed JSON: %s", exc)
        return JSONResponse(
            status_code=400,
            content={"status": "error", "detail": f"Malformed JSON: {exc}"},
        )

    if x_github_event == "ping":
        logger.info("Handled GitHub ping event")
        return {"status": "ok", "event": "ping"}

    background_tasks.add_task(process_event, x_github_event, payload)
    logger.info("Queued background processing for event=%s", x_github_event)
    return {"status": "ok", "event": x_github_event}
